/* ------------------------------------------------------------------ *
 * StatChip — a small mono figure with a label. The number is set in
 * Geist Mono with tabular figures so it reads as instrument data.
 * ------------------------------------------------------------------ */
export function StatChip({
  value,
  label,
  tone = "default",
}: {
  value: string;
  label: string;
  tone?: "default" | "emerald" | "amber";
}) {
  const valueTone =
    tone === "emerald"
      ? "text-brand-700 dark:text-brand-300"
      : tone === "amber"
        ? "text-gold-600"
        : "text-slate-900 dark:text-slate-50";
  return (
    <div className="flex flex-col">
      <span
        className={cn("font-mono text-sm font-semibold", valueTone)}
        data-numeric
      >
        {value}
      </span>
      <span className="mt-0.5 text-[11px] text-slate-500 dark:text-slate-400">{label}</span>
    </div>
  );
}
